package com.lovemaptually.service;
import com.lovemaptually.dto.response.*;import com.lovemaptually.entity.*;import com.lovemaptually.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor
public class PreferenceService {private final AccessService access;private final GroupMemberRepository groupMembers;private final UserTagRepository userTags;
 @Transactional(readOnly=true) public GroupPreferencesResponse get(long uid,long gid){access.member(gid,uid);List<Long> ids=groupMembers.findAllByGroupGroupIdAndLeftAtIsNullOrderByJoinedAt(gid).stream().map(m->m.getUser().getUserId()).toList();Map<Long,List<UserTag>> by=new LinkedHashMap<>();userTags.findAllByUserUserIdIn(ids).forEach(ut->by.computeIfAbsent(ut.getTag().getTagId(),x->new ArrayList<>()).add(ut));List<PreferenceItemResponse> prefs=new ArrayList<>();for(List<UserTag> rows:by.values()){Tag tag=rows.getFirst().getTag();List<PreferenceMemberResponse> ms=rows.stream().map(ut->{String side=side(ut);if(side==null)return null;return new PreferenceMemberResponse(ut.getUser().getUserId(),ut.getUser().getNickname(),side,"HIGH".equals(side)?tag.getHighLabel():tag.getLowLabel(),ut.getWantHighCount(),ut.getWantLowCount());}).filter(Objects::nonNull).toList();Set<String>sides=new HashSet<>();ms.forEach(m->sides.add(m.side()));String label=ms.size()==1?"ONE_SIDED":sides.size()==1?"ALL_SAME":"SPLIT";String side=sides.size()==1?sides.iterator().next():null;prefs.add(new PreferenceItemResponse(tag.getTagId(),tag.getName(),tag.getAxis().name(),label,side,side==null?null:"HIGH".equals(side)?tag.getHighLabel():tag.getLowLabel(),ms.size(),ms));}return new GroupPreferencesResponse(gid,prefs);}
 private String side(UserTag ut){return Objects.equals(ut.getWantHighCount(),ut.getWantLowCount())?null:ut.getWantHighCount()>ut.getWantLowCount()?"HIGH":"LOW";}}
